bool ABRBossTeamCoordinator::CanStartAttack(ABRBossBase* RequestingBoss) const
{
	if (!RequestingBoss)
	{
		return false;
	}

	if (bAllowSimultaneousAttacks)
	{
		return true;
	}

	if (ActiveAttacker && ActiveAttacker != RequestingBoss)
	{
		return false;
	}

	const UWorld* World = GetWorld();
	return !World || World->GetTimeSeconds() - LastAttackFinishedTime >= TeamAttackGap;
}

void ABRBossBase::RecoverFromGroggy()
{
	if (bIsDead || bIsPhaseTransitioning || !bIsGroggy)
	{
		return;
	}

	if (bIsBeingExecuted)
	{
		GetWorldTimerManager().SetTimer(GroggyTimerHandle, this, &ABRBossBase::RecoverFromGroggy, 0.1f, false);
		return;
	}

	bIsGroggy = false;
	NotifyBossAnimationStage(EBRBossAnimationStage::Idle);

	if (StatComponent)
	{
		StatComponent->ResetGroggy();
	}

	OnBossRecoveredFromGroggy.Broadcast();
	OnBossRecoveredFromGroggyInternal();

void AExceptionPlayerController::BindPlayerHUDToPawn()
{
	if (!IsLocalPlayerController() || IsInTitleLevel())
	{
		return;
	}

